codes.cpp:
#include <iostream>
#include <string>

// OOP overkill for config
class DatabaseConfig {
public:
    DatabaseConfig(std::string host, int port)
        : host_(std::move(host)), port_(port) {}

    std::string getHost() const { return host_; }
    int getPort() const { return port_; }

private:
    std::string host_;
    int port_;
};

int main() {
    DatabaseConfig config("localhost", 5432);

    std::cout << config.getHost() << std::endl;
    std::cout << config.getPort() << std::endl;

    return 0;
}
